function extractNamedEntity(text,words){const marker=words.join('|'),patterns=[new RegExp(`(?:${marker})(?:\\s+جدید)?(?:\\s+(?:ایجاد|ثبت|تعریف|اضافه|بساز)(?:\\s+کن)?)?(?:\\s+(?:به نام|بنام|اسمش|نام))\\s+([^،,.]+)`),new RegExp(`(?:به نام|بنام|اسمش)\\s+([^،,.]+?)\\s+(?:را|برای|به عنوان|${marker})`)];for(const re of patterns){const m=text.match(re);if(m)return m[1].replace(/\\s+(?:برای|در)\\s+پروژه.*$/,'').replace(/\\s+(?:جوشکار|بنا|برقکار|فروشنده|مسئول فروش|نگهبان|کارگر).*$/,'').trim()}return''}
