const smartAnalyzeEntitiesBase=analyzeSmartDocument;analyzeSmartDocument=function(){smartAnalyzeEntitiesBase();const text=document.getElementById('smartDocCommand')?.value.trim()||'';let project=db.projects.find(x=>text.includes(x.name)),person=db.people.find(x=>text.includes(x.name));const parsed=PeymanyarCommand.parse(text,db,todayFa());let projectName=project?.name||'',personName=person?.name||'';if(!projectName&&parsed.intent==='project_create'&&parsed.name)projectName=parsed.name;if(!projectName)projectName=extractNamedEntity(text,['پروژه']);if(!personName)personName=extractNamedEntity(text,['پیمانکار','فروشنده','مسئول فروش','طرف حساب','نیرو','فرد']);if(projectName){setSelectValue('smartProject',projectName);if(!db.projects.some(x=>x.name===projectName))pendingEntities.project={name:projectName}}if(personName){setSelectValue('smartPerson',personName);if(!db.people.some(x=>x.name===personName))pendingEntities.person={name:personName,role:inferPartyRole(text)}}updateSmartQuestions();showPendingEntities()}
