const financeCategoryBase=finance;finance=function(){const html=financeCategoryBase(),cats=allFinancialCategories();if(!cats.length)return html;const bar=`<section class="category-strip"><strong>دسته‌های مالی</strong><div>${cats.map(x=>`<button type="button" onclick="filter='${esc(x)}';render()">${esc(x)}</button>`).join('')}</div></section>`;return html.replace('<div class="detail-kpis">',bar+'<div class="detail-kpis">')}
