let smartOcrBusy=false;
function loadTesseract(){if(window.Tesseract)return Promise.resolve(window.Tesseract);return new Promise((resolve,reject)=>{const old=document.getElementById('tesseractLoader');if(old){old.addEventListener('load',()=>resolve(window.Tesseract),{once:true});old.addEventListener('error',reject,{once:true});return}const script=document.createElement('script');script.id='tesseractLoader';script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';script.onload=()=>resolve(window.Tesseract);script.onerror=reject;document.head.appendChild(script)})}
function ocrDigits(text){return normalizeDigits((text||'').replace(/[٬,]/g,''))}
function extractReceiptFields(text){const raw=ocrDigits(text),amountMatches=[...raw.matchAll(/(?:مبلغ|جمع|برداشت|واریز|انتقال)[^\d]{0,25}(\d{4,15})\s*(ریال|تومان)?/g)],fallback=[...raw.matchAll(/\b(\d{5,15})\s*(ریال|تومان)\b/g)],candidate=(amountMatches.at(-1)||fallback.at(-1)),amount=candidate?Number(candidate[1])/(candidate[2]==='ریال'?10:1):0,dateMatch=raw.match(/(1[34]\d{2})[\/\-.](\d{1,2})[\/\-.](\d{1,2})/),tracking=(raw.match(/(?:پیگیری|مرجع|رهگیری)[^\d]{0,12}(\d{5,30})/)||[])[1]||'';return{amount,date:dateMatch?`${dateMatch[1]}/${dateMatch[2].padStart(2,'0')}/${dateMatch[3].padStart(2,'0')}`:'',tracking}}
async function readSmartReceiptImage(){if(smartOcrBusy||!pendingSmartFile||!pendingSmartFile.type.startsWith('image/'))return;smartOcrBusy=true;const box=document.getElementById('smartQuestions');if(box)box.innerHTML='<strong>در حال خواندن مبلغ و تاریخ از تصویر…</strong><p>بار اول ممکن است کمی طول بکشد.</p>';try{const OCR=await loadTesseract();if(!OCR)throw new Error('ocr-unavailable');const worker=await OCR.createWorker('fas+eng',1,{logger:m=>{if(box&&m.status==='recognizing text')box.innerHTML=`<strong>در حال خواندن تصویر… ${fa(Math.round((m.progress||0)*100))}٪</strong>`}}),result=await worker.recognize(pendingSmartFile);await worker.terminate();const text=result.data.text||'',fields=extractReceiptFields(text);if(fields.amount){const amount=document.getElementById('smartAmount');amount.value=fa(Math.round(fields.amount));amount.dispatchEvent(new Event('input',{bubbles:true}))}if(fields.date)document.getElementById('smartDate').value=fields.date;if(!v('smartType'))setSelectValue('smartType',/واریز|دریافت/.test(text)?'رسید واریزی':'رسید پرداخت');const command=document.getElementById('smartDocCommand');if(command&&!command.value.trim())command.value=`رسید بانکی${fields.tracking?' شماره پیگیری '+fields.tracking:''}`;analyzeSmartDocument();toast(fields.amount||fields.date?'اطلاعات رسید از تصویر خوانده شد':'متن تصویر خوانده شد؛ موارد نامشخص را تکمیل کن')}catch(e){updateSmartQuestions();toast('خواندن خودکار تصویر انجام نشد؛ توضیح سند را بنویس')}finally{smartOcrBusy=false}}
const smartFileOcrBase=smartFileSelected;smartFileSelected=function(input){smartFileOcrBase(input);if(pendingSmartFile?.type.startsWith('image/'))readSmartReceiptImage()}
const baseParseQuick=parseQuick;parseQuick=function(){const input=document.getElementById('quickText'),box=document.getElementById('parsedResult');if(!input||!box)return;const text=input.value.trim();if(!text)return toast('ابتدا فرمان را بگو یا بنویس');const cmd=PeymanyarCommand.parse(text,db,todayFa());if(cmd.intent!=='financial_query')return baseParseQuick();const rows=reportRows({project:cmd.project,person:cmd.person,dateFrom:cmd.dateFrom,dateTo:cmd.dateTo}),sum=reportSummary(rows),a=contractAccount(cmd.project,cmd.person);activeReport={title:`گزارش مالی${cmd.project?' پروژه '+cmd.project:''}${cmd.person?' - '+cmd.person:''}`,rows,project:cmd.project,person:cmd.person,dateFrom:cmd.dateFrom,dateTo:cmd.dateTo};box.innerHTML=`<div class="parsed"><div class="command-title"><strong>${esc(activeReport.title)}</strong><span class="command-badge">${fa(rows.length)} ردیف</span></div><div class="parsed-grid"><div><small>دریافتی</small>${money(sum.received)}</div><div><small>پرداخت</small>${money(sum.paid)}</div><div><small>قرارداد</small>${money(a.contract)}</div><div><small>مانده قرارداد</small>${money(a.remain)}</div></div><div class="report-actions"><button onclick="showReportModal()">نمایش ریز گزارش</button><button onclick="exportActiveCSV()">Excel</button><button onclick="exportActiveWord()">Word</button><button onclick="printActiveReport()">PDF</button></div></div>`}
